def count_special_letters(word: str) -> int:
    seen_lower = set()
    seen_upper = set()
    for char in word:
        lower_char = char.lower()
        if char.islower():
            seen_lower.add(lower_char)
        else:
            seen_upper.add(lower_char)
    return len(seen_lower & seen_upper)
```

