            elif rank[px] > rank[py]:
                parent[py] = px
            else:
                parent[py] = px
                rank[px] += 1
            return True
        for i in combo:
            u, v, _ = edges[i]
            if not union(u, v):
                return False
        return True

    for combo in combinations(range(M), N - 1):
        if is_tree(combo):
            s = 0
            for i in combo:
                s = (s + edges[i][2]) % K
            if s < min_cost:
                min_cost = s
    print(min_cost)

solve()
