        polys.append(g)
    total_cells = 0
    for g in polys:
        pos = get_pos(g)
        total_cells += len(pos)
    if total_cells != 16:
        print("No")
        return
    mask_sets = []
    FULL = (1 << 16) - 1
    for g in polys:
        rots = [g]
        for _ in range(3):
            rots.append(rotate_once(rots[-1]))
        mset = set()
        for rot in rots:
            pos = get_pos(rot)
            ncells = len(pos)
            for dr in range(-3, 4):
                for dc in range(-3, 4):
                    mask = 0
                    fits = True
                    for r, c in pos:
                        nr, nc = r + dr, c + dc
                        if not (0 <= nr < 4 and 0 <= nc < 4):
                            fits = False
                            break
                        bitpos = nr * 4 + nc
                        bit = 1 << bitpos
                        if mask & bit != 0:
