def minBalancedPartitions(s: str) -> int:
    n = len(s)
    INF = n + 1
    dp = [INF] * (n + 1)
    dp[0] = 0
    prefix = [[0] * 26 for _ in range(n + 1)]
    a = ord('a')
    for i in range(n):
        for c in range(26):
            prefix[i + 1][c] = prefix[i][c]
        prefix[i + 1][ord(s[i]) - a] += 1

    def is_balanced(left: int, right: int) -> bool:
        freq = -1
        for c in range(26):
            f = prefix[right + 1][c] - prefix[left][c]
            if f > 0:
                if freq == -1:
                    freq = f
                elif f != freq:
                    return False
        return True

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] != INF and is_balanced(j, i - 1):
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n]
