    def taka_wins(state):
        if state in memo:
            return memo[state]
        painted_count = sum(x != 0 for x in state)
        is_taka_turn = (painted_count % 2 == 0)
        whites = [k for k in range(9) if state[k] == 0]
        if not whites:
            tscore = sum(A_flat[p] for p in range(9) if state[p] == 1)
            ascore = sum(A_flat[p] for p in range(9) if state[p] == 2)
            res = tscore > ascore
            memo[state] = res
            return res

        if is_taka_turn:
            for k in whites:
                new_state_list = list(state)
                new_state_list[k] = 1
                new_state = tuple(new_state_list)
                if has_three(new_state, 1):
                    memo[state] = True
                    return True
                elif has_three(new_state, 2):
                    outcome = False
                elif all(x != 0 for x in new_state):
                    tscore = sum(A_flat[p] for p in range(9) if new_state[p] == 1)
                    ascore = sum(A_flat[p] for p in range(9) if new_state[p] == 2)
                    outcome = tscore > ascore
                else:
                    outcome = taka_wins(new_state)
                if outcome:
                    memo[state] = True
                    return True
            memo[state] = False
            return False
        else:
            for k in whites:
                new_state_list = list(state)
                new_state_list[k] = 2
                new_state = tuple(new_state_list)
                if has_three(new_state, 1):
                    outcome = True
                elif has_three(new_state, 2):
