        m = len(s)
        memo = {}
        def dfs(pos: int, cur: int) -> bool:
            if pos == m:
                return cur == target
            key = (pos, cur)
            if key in memo:
                return memo[key]
            res = False
            num = 0
            for j in range(pos, m):
                num = num * 10 + int(s[j])
                new_cur = cur + num
                if new_cur > target:
                    break
                if dfs(j + 1, new_cur):
                    res = True
                    break
            memo[key] = res
            return res
        return dfs(0, 0)

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        s = str(sq)
        if can_sum(s, i):
            total += sq
    return total
