def count_relevant_set_bits_up_to(n: int, b: int) -> int:
    if n == 0:
        return 0
    period = 1 << (b + 1)
    full = n // period
    cnt = full * (1 << b)
    rem = n % period
    thresh = 1 << b
    if rem >= thresh:
        cnt += rem - thresh + 1
    return cnt

def sum_prices_up_to(n: int, x: int) -> int:
    if n <= 0:
        return 0
    total = 0
    p = x
    while True:
        b = p - 1
        if (1 << b) > n:
            break
        total += count_relevant_set_bits_up_to(n, b)
        p += x
    return total

def solution(k: int, x: int) -> int:
    low = 0
    high = 2 * 10**18
    while low < high:
        mid = (low + high + 1) // 2
        if sum_prices_up_to(mid, x) <= k:
            low = mid
        else:
            high = mid - 1
    return low
