def powerful_array_product(queries):
    def count_bit(k, n):
        if n == 0:
            return 0
        period = 1 << (k + 1)
        full = n // period
        contrib = full * (1 << k)
        rem = n % period
        if rem >= (1 << k):
            contrib += rem - (1 << k) + 1
        return contrib

    def get_len(n):
        if n == 0:
            return 0
        total = 0
        for k in range(64):
            total += count_bit(k, n)
        return total

    def get_exp(n):
        if n == 0:
            return 0
        total = 0
        for k in range(64):
            total += k * count_bit(k, n)
        return total

    def prefix_exp(P):
        if P < 0:
            return 0
        target = P + 1
        lo = 1
        hi = 10**16
        while lo < hi:
            mid = (lo + hi) // 2
            if get_len(mid) >= target:
                hi = mid
            else:
                lo = mid + 1
        N = lo
        prev_len = get_len(N - 1)
        M_needed = target - prev_len
        # get bits of N in order
        bits = []
        temp = N
        k = 0
        while temp > 0:
            if temp & 1:
                bits.append(k)
            temp >>= 1
            k += 1
        partial = sum(bits[:M_needed])
        return get_exp(N - 1) + partial

    answer = []
    for q in queries:
        L, R, M = q
        exp_total = prefix_exp(R) - prefix_exp(L - 1)
        ans = pow(2, exp_total, M)
        answer.append(ans)
    return answer
