def maxGroups(usageLimits):
    n = len(usageLimits)
    if n == 0:
        return 0
    sorted_l = sorted(usageLimits, reverse=True)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + sorted_l[i]

    def can_form(k):
        if k == 0:
            return True
        for m in range(1, k + 1):
            # Binary search for the smallest p where sorted_l[p] <= m
            left, right = 0, n
            while left < right:
                mid = (left + right) // 2
                if sorted_l[mid] > m:
                    left = mid + 1
                else:
                    right = mid
            p = left
            total_cap = m * p + prefix[n] - prefix[p]
            need = m * (2 * k - m + 1) // 2
            if total_cap < need:
                return False
        return True

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_form(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
