from collections import deque
from typing import List

def minCost(nums: List[int], x: int) -> int:
    n = len(nums)
    extended = nums + nums
    N = len(extended)
    ans = float('inf')
    for m in range(n):
        w = m + 1
        dq = deque()
        mins_list = []
        for i in range(N):
            while dq and dq[0] < i - w + 1:
                dq.popleft()
            while dq and extended[dq[-1]] >= extended[i]:
                dq.pop()
            dq.append(i)
            if i >= w - 1:
                mins_list.append(extended[dq[0]])
        total_coll = 0
        for t in range(n):
            end_pos = t + n
            k = end_pos - w + 1
            total_coll += mins_list[k]
        total = total_coll + m * x
        if total < ans:
            ans = total
    return int(ans)
```

